#!/usr/bin/env node
// MA-010. The standing test for the nightly's two voice rules, the pattern of scripts/test-vercel-ignore.ts:
// real cases, each asserting the answer the rule must give, a count, and an exit code. Run by the
// nightly workflow before the audit, so a rule that has drifted fails the night instead of writing a
// report; run by hand with `node scripts/audit/nightly/test-voice-rules.mjs`.
//
// The superlative rule is a compliance rule: RECO bars a registrant from an unsubstantiated superlative
// about themselves, their brokerage or a property. The failure that matters is the quiet one, a claim
// the rule stops seeing, so the violations come first and every legitimate case must be exempt for the
// RIGHT reason, not merely silent. Sources: "task" (the MA-010 brief), "production" (served on
// 2026-09-23, the capture behind scratchpad/ma010/, page named), "red team" / "red team 2" (a break
// MA-010's red team executed against an earlier draft, confirmed), "mutant" (a case that kills a mutant
// of checks.mjs that earlier fixtures let survive).
//
// The em-dash rule counts punctuation in prose (checks.mjs, proseOnly). Its cases are pages, run through
// the same pageFindings the nightly runs.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { SUPERLATIVES, REGISTERED, superlativeHits, pageFindings } from './checks.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
let assertions = 0;
const failures = [];
const ok = (cond, label) => { assertions++; if (!cond) failures.push(label); return cond; };
const fires = (s) => superlativeHits(s).some((h) => !h.exemption);
const show = (s) => superlativeHits(s).map((h) => `${h.match}:${h.exemption || 'FIRES'}`).join(' ') || 'no hit';

