let pPass = 0;
for (const [why, html, listing, want] of SUP_PAGES) {
  const got = supKeys(html, listing).sort();
  if (ok(JSON.stringify(got) === JSON.stringify([...want].sort()), `SUPERLATIVE PAGE ${why}: got ${JSON.stringify(got)}, expected ${JSON.stringify(want)}`)) pPass++;
}

// ── 4. The registered names come from the data files, and the vocabulary is the generators' own ──
ok(REGISTERED.fromFiles, 'the registered names were not read from src/data (fallback list in use)');
for (const n of ['Best Road', 'Best Rd', 'Brian Best Park']) ok(REGISTERED.names.includes(n), `registered names lack "${n}"`);
ok(REGISTERED.slugs.includes('best-road-milton'), 'registered slugs lack best-road-milton');
ok(REGISTERED.bases.has('ferguson') && REGISTERED.supBases.has('best'), 'registered street bases lack ferguson or best');
const validator = fs.readFileSync(path.join(ROOT, 'src/lib/ai/validateStreetGeneration.ts'), 'utf8');
const phrases = [...(validator.match(/SUPERLATIVE_PHRASES\s*=\s*\[([\s\S]*?)\]/) || [, ''])[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]);
ok(phrases.length > 0 && phrases.join('|') === SUPERLATIVES.join('|'), `SUPERLATIVES (${SUPERLATIVES.length}) != SUPERLATIVE_PHRASES (${phrases.length}): the lists drifted`);

// ── 5. The em-dash rule: a dash counts when it punctuates prose ──────────────────────────────────
const dashes = (html, listing = false) => {
  const f = pageFindings({ html, path: listing ? '/listings/W1' : '/fixture', base: 'https://miltonly.com', listing }).findings.filter((x) => x.code === 'em-dash');
  const n = (key) => { const x = f.find((y) => y.key === key); return x ? { n: +x.detail.split(' ')[0], detail: x.detail } : { n: 0, detail: '' }; };
  return { text: n('text'), title: n('title'), meta: n('meta') };
};
