let ePass = 0;
for (const [why, body, want] of EM_CASES) { const got = dashes(page({ body })).text.n; if (ok(got === want, `EM-DASH ${why}: counted ${got}, expected ${want}`)) ePass++; }
const EM_EXTRA = [
  // nav and prose on one page: the prose counts once and the excerpt quotes the prose, not "X—"
  ['nav + bio: one, quoting the bio', () => { const r = dashes(page({ body: AZ + BIO })).text; return r.n === 1 && /far more than price/.test(r.detail) && !/X—/.test(r.detail); }],
  ['a long menu then the bio: the excerpt quotes the bio (mutant)', () => { const r = dashes(page({ body: `<nav class="site-nav" aria-label="Site"><ul>${MENU}${MENU}</ul></nav>${BIO}` })).text; return r.n === 1 && /far more than price/.test(r.detail); }],
  // the title and the meta description are the site's own words and stay in scope
  ['a dash in the title (production: /about)', () => dashes(page({ title: `About Aamir Yaqoob ${D} Milton Real Estate Agent`, body: P })).title.n === 1],
  ['an entity dash in the title (mutant)', () => dashes(page({ title: 'About Aamir Yaqoob &#8212; Milton Real Estate Agent', body: P })).title.n === 1],
  ['a dash in the meta (production: /)', () => dashes(page({ meta: `The Milton Real Estate Encyclopedia ${D} search homes for sale, compare streets and neighbourhoods.`, body: P })).meta.n === 1],
  ['a dash in the title of a listing page (mutant)', () => dashes(page({ title: `1593 Rose Way ${D} 3 bed townhouse for sale in Milton`, body: P }), true).title.n === 1],
  ['a dash in the meta of a listing page (mutant)', () => dashes(page({ meta: `A three-bedroom townhouse in Cobban ${D} two baths, a garage and a fenced yard.`, body: P }), true).meta.n === 1],
  // listing pages: our copy outside labelled remarks is checked, the seller's words are not
  ['a listing page with labelled remarks checks our copy', () => dashes(page({ body: `${REMARKS}${BIO}` }), true).text.n === 1],
  ["the seller's remarks are not ours (mutant)", () => dashes(page({ body: `<section><h2>Listing agent's remarks</h2><div data-remarks="">Stunning detached home on a quiet crescent ${D} backs onto the ravine.</div></section><p>Plain.</p>` }), true).text.n === 0],
  ['a listing page without a remarks block stands the body down (mutant)', () => dashes(page({ body: `<p>Stunning detached home ${D} must see, backs onto the ravine.</p>` }), true).text.n === 0],
  // the share card is read by the superlative check only
  ['a dash in og:title is not an em-dash finding (mutant)', () => { const r = dashes(page({ title: 'About Aamir Yaqoob, Milton Real Estate Agent', head: `<meta property="og:title" content="About Aamir Yaqoob ${D} Milton Real Estate Agent | Miltonly.com"/>`, body: P })); return r.text.n === 0 && r.title.n === 0; }],
];
for (const [why, fn] of EM_EXTRA) if (ok(fn(), `EM-DASH ${why}`)) ePass++;
const emTotal = EM_CASES.length + EM_EXTRA.length;

console.log(`[voice-rules] superlative: ${vPass}/${VIOLATIONS.length} violations fire, ${lPass}/${LEGITIMATE.length} legitimate uses exempt for the named reason, ${pPass}/${SUP_PAGES.length} page cases`);
console.log(`[voice-rules] em-dash: ${ePass}/${emTotal} page cases`);
if (failures.length > 0) {
  console.error(`[voice-rules] FAIL: ${failures.length} of ${assertions} assertions:`);
  for (const f of failures) console.error(`  ${f}`);
  process.exit(1);
}
console.log(`[voice-rules] PASS: ${assertions} assertions.`);
